# Analyze original pattern more deeply
input_grid = [
    [0, 5, 5, 0, 5, 0],
    [0, 5, 0, 0, 0, 5],
    [5, 0, 5, 0, 5, 0],
    [5, 5, 5, 0, 0, 0],
