            pass
        else:
            diag_sym = False
print(f"Diagonal symmetry (main): {diag_sym}")

# Check anti-diagonal symmetry
anti_sym = True
for i in range(n):
    for j in range(n):
        if input_grid[i][j] == input_grid[n-1-j][n-1-i]:
            pass
        else:
