                if 0 <= ni < n and 0 <= nj < n:
                    if input_grid[ni][nj] == 5:
                        cnt += 1
        neighbor_sum[i][j] = cnt
print("Neighbor count (5s around each cell):")
print(json.dumps(neighbor_sum))

# Maybe it's about finding empty space not touching boundary
input_grid = [
    [0, 5, 5, 0, 5, 0],
