    [5, 5, 5, 0, 0, 0],
    [0, 5, 0, 5, 5, 5],
    [0, 0, 5, 0, 5, 0]
]

n = 6
boundary_adjacent = [[False for _ in range(n)] for _ in range(n)]
for i in range(n):
    for j in range(n):
        if i == 0 or i == n-1 or j == 0 or j == n-1:
            boundary_adjacent[i][j] = True

# Flood fill 0s from outside
direction = [(0, 1), (0, -1), (1, 0), (-1, 0)]
visited_outer = set()
for i in range(n):
    for j in range(n):
        if input_grid[i][j] == 0 and boundary_adjacent[i][j]:
            stack = [(i, j)]
            while stack:
                r, c = stack.pop()
                if (r, c) in visited_outer:
                    continue
                visited_outer.add((r, c))
                for dr, dc in direction:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        if input_grid[nr][nc] == 0 and (nr, nc) not in visited_outer:
                            stack.append((nr, nc))

# Cells reachable from outside (0s) vs trapped 0s
trapped = [(i,j) for i in range(n) for j in range(n) if input_grid[i][j] == 0 and (i,j) not in visited_outer]
print("Trapped 0s:", trapped)

# Output: 0 where input has 0 and trapped, 5 elsewhere
output = [[0 if input_grid[i][j] == 0 and (i,j) not in visited_outer else 5 if input_grid[i][j] == 5 else 0 for j in range(n)] for i in range(n)]
